"""pytest unit tests for is_rotated_v1."""

from target import is_rotated_v1


def test_empty_strings():
    assert is_rotated_v1("", "") is True


def test_identical_strings():
    assert is_rotated_v1("abc", "abc") is True


def test_single_rotation():
    assert is_rotated_v1("abc", "bca") is True


def test_double_rotation():
    assert is_rotated_v1("abc", "cab") is True


def test_no_rotation():
    assert is_rotated_v1("abc", "def") is False


def test_different_lengths():
    assert is_rotated_v1("ab", "abc") is False


def test_palindrome_rotation():
    assert is_rotated_v1("abba", "bbaa") is True


def test_single_char():
    assert is_rotated_v1("a", "a") is True
    assert is_rotated_v1("a", "b") is False

