from target import encrypt


def test_encrypt_positive_key():
    result = encrypt("HELLO", 2)
    assert result == "HELLO"


def test_encrypt_key_one_returns_input():
    result = encrypt("ANYTHING", 1)
    assert result == "ANYTHING"


def test_encrypt_string_shorter_than_key():
    result = encrypt("AB", 5)
    assert result == "AB"


def test_encrypt_key_negative_raises_value_error():
    with pytest.raises(ValueError, match="Height of grid can't be 0 or negative"):
        encrypt("TEST", -1)


def test_encrypt_key_zero_raises_value_error():
    with pytest.raises(ValueError, match="Height of grid can't be 0 or negative"):
        encrypt("TEST", 0)


def test_encrypt_basic_example():
    result = encrypt("HELLO WORLD", 3)
    assert result == "HOO ELRLWD "

