import pytest
from target import is_luhn


def test_valid_visa():
    # 4532015112830366 is a valid Visa number
    assert is_luhn("4532015112830366") is True


def test_invalid_visa():
    # 4532015112830367 is not a valid Visa number (check digit off by 1)
    assert is_luhn("4532015112830367") is False


def test_valid_mastercard():
    # 5555555555554444 is a valid Mastercard number
    assert is_luhn("5555555555554444") is True


def test_invalid_mastercard():
    # 5555555555555555 is not a valid Mastercard number
