from target import is_palindrome


def test_empty_list():
    """An empty list is considered a palindrome."""
    assert is_palindrome(None) is True


def test_single_node():
    """A single node list is considered a palindrome."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    assert is_palindrome(head) is True


def test_two_nodes_same():
    """Two nodes with the same value form a palindrome."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    head.next = Node(1)
    assert is_palindrome(head) is True


def test_two_nodes_different():
    """Two nodes with different values do not form a palindrome."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    head.next = Node(2)
    assert is_palindrome(head) is False


def test_palindrome_odd_length():
    """Odd length palindrome: 1 -> 2 -> 1."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    head.next = Node(2)
    head.next.next = Node(1)
    assert is_palindrome(head) is True


def test_palindrome_even_length():
    """Even length palindrome: 1 -> 2 -> 2 -> 1."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    head.next = Node(2)
    head.next.next = Node(2)
    head.next.next.next = Node(1)
    assert is_palindrome(head) is True


def test_non_palindrome():
    """Non-palindrome: 1 -> 2 -> 3."""
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    head = Node(1)
    head.next = Node(2)
    head.next.next = Node(3)
    assert is_palindrome(head) is False


def test_palindrome_with_duplicates():
