"""Pytest unit tests for bin_to_decimal function."""

from target import bin_to_decimal


def test_positive_binary_number():
    """Test that a valid positive binary string is converted correctly."""
    assert bin_to_decimal("1010") == 10


def test_positive_single_one():
    """Test that a single '1' converts to 1."""
    assert bin_to_decimal("1") == 1


def test_positive_single_zero():
    """Test that a single '0' converts to 0."""
    assert bin_to_decimal("0") == 0


def test_negative_binary_number():
    """Test that a valid negative binary string is converted correctly."""
    assert bin_to_decimal("-101") == -5


def test_empty_string_raises_value_error():
    """Test that an empty string raises ValueError."""
    try:
        bin_to_decimal("")
        assert False, "Expected ValueError to be raised"
    except ValueError as e:
        assert str(e) == "Empty string was passed to the function"


def test_non_binary_values_raise_value_error():
    """Test that strings containing non-binary characters raise ValueError."""
    # Testing with '2' in the string
    try:
        bin_to_decimal("1021")
        assert False, "Expected ValueError to be raised"
    except ValueError as e:
        assert str(e) == "Non-binary value was passed to the function"

    # Testing with letters
    try:
        bin_to_decimal("101a")
        assert False, "Expected ValueError to be raised"
    except ValueError as e:
        assert str(e) == "Non-binary value was passed to the function"


def test_whitespace_only_string_raises_value_error():
    """Test that a string with only whitespace raises ValueError."""
    try:
        bin_to_decimal("   ")
        assert False, "Expected ValueError to be raised"
    except ValueError as e:
        assert str(e) == "Empty string was passed to the function"

