        4: [3, 2],
    }
    result = compute_bridges(graph)
    assert result == [(0, 1)]


def compute_bridges(graph: dict[int, list[int]]) -> list[tuple[int, int]]:
    id_ = 0
    n = len(graph)
    low = [0] * n
    visited = [False] * n

    def dfs(at, parent, bridges, id_) -> None:
        visited[at] = True
        low[at] = id_
        id_ += 1
        for to in graph[at]:
            if to == parent:
                pass
            elif not visited[to]:
                dfs(to, at, bridges, id_)
                low[at] = min(low[at], low[to])
                if id_ <= low[to]:
                    bridges.append((at, to) if at < to else (to, at))
            else:
                # Fixed: Use id_ (the discovery time of the current node) instead of low[to]
                low[at] = min(low[at], id_)

    bridges: list[tuple[int, int]] = []
    for i in range(n):
        if not visited[i]:
            dfs(i, -1, bridges, id_)
    return bridges

