def array_sum_combinations(array_a: list[int], array_b: list[int], array_c: list[int], target: int) -> list[list[int]]:
    v1_ = [array_a, array_b, array_c]

    def _is_complete(constructed_so_far: list[int]) -> tuple[bool, bool]:
        # Fixed logic: check length first, then sum. 
        # A combination is "complete" if it has 3 elements OR its sum meets/exceeds the target.
        # We distinguish between "exceeded" (v4_) and "exact match" (v5_).
        v3_ = sum(constructed_so_far)
        v4_ = len(constructed_so_far) >= 3 or v3_ >= target
        v5_ = v3_ == target and len(constructed_so_far) == 3
        return (v4_, v5_)

    def _get_candidates(constructed_so_far: list[int]) -> list[int]:
        # Returns the next array to pick from based on how many elements are already chosen
        return v1_[len(constructed_so_far)]

    def _backtrack(constructed_so_far: list[int] | None = None, result: list[list[int]] | None = None) -> None:
        # Python 3.9 compatible type hints
        if constructed_so_far is None:
            constructed_so_far = []
        if result is None:
            result = []

        (v4_, v5_) = _is_complete(constructed_so_far)

        if v4_:
            if v5_:
                result.append(list(constructed_so_far))
            return

        v6_ = _get_candidates(constructed_so_far)
        for v7_ in v6_:
            constructed_so_far.append(v7_)
            _backtrack(constructed_so_far, result)
            constructed_so_far.pop()

    result: list[list[int]] = []
    _backtrack([], result)
    return result

